// テキスト内に含まれる辞書用語を検出し、最初にマッチした語を返す（クロスリンク用）。
// 用語名は「MLA（潜在注意）」等の括弧前主要部と全体の両方で照合し、2文字以上のみ対象。
function findLexTerm(text) {
  if (!text) return null;
  for (const g of LEXICON) {
    const names = [];
    [g.t, g.en].filter(Boolean).forEach((nm) => {
      names.push(nm);
      const core = nm.split(/[（(／/]/)[0].trim();
      if (core && core !== nm) names.push(core);
    });
    for (const nm of names) {
      if (nm.length >= 3 && text.includes(nm)) return g;
    }
  }
  return null;
}

